// Russian adaptations and original practice based on the attributed open textbooks.
window.BoraCourses=[
{id:'pt',language:'pt-BR',title:'Бразильский португальский: первые разговоры',description:'От первого oi до рассказа о вчерашнем дне. Для общения в Бразилии, маленькими шагами.',source:'Português para principiantes · UW–Madison',url:'https://wisc.pb.unizin.org/portuguese/',license:'CC BY-NC-SA 4.0',licenseUrl:'https://creativecommons.org/licenses/by-nc-sa/4.0/',lessons:[
{id:'oi',title:'Начать разговор',scene:'Ты встречаешь нового соседа. Нужно поздороваться и ответить на «Как дела?».',idea:'Oi — дружеское «Привет». Tudo bem? — «Как дела?». Та же фраза без вопроса может быть ответом: «Всё хорошо». Здесь пока не нужно разбирать каждое слово: запомни маленький готовый разговор.',examples:[['Oi! Tudo bem?','Привет! Как дела?'],['Tudo bem, e você?','Всё хорошо, а у тебя?'],['Até amanhã!','До завтра!']],quiz:[['Сосед только подошёл. Что скажешь?',['Oi! Tudo bem?','Até amanhã!','Boa noite e tchau!'],0,'Oi начинает дружеский разговор. Até amanhã говорят при прощании.'],['Как спросить «А у тебя?»',['E você?','Eu sou.','Até amanhã.'],0,'E — «и / а», você — «ты / вы».']],write:['Напиши по-португальски «Привет! Как дела?»',['oi tudo bem'],'Oi! Tudo bem?'],mission:'Представь соседа и произнеси приветствие вслух. Затем ответь за него.',topic:'Приветствия и знакомство'},
{id:'nome',title:'Представиться',scene:'В кафе бариста спрашивает твоё имя.',idea:'Eu — «я». Sou — форма глагола ser для «я»: «являюсь». В русском «Я Анна» обходится без глагола; в португальском он нужен: Eu sou Ana. Ещё можно сказать Meu nome é Ana — «Меня зовут Анна».',examples:[['Eu sou Ana.','Я Анна.'],['Meu nome é Paulo.','Меня зовут Паулу.'],['Como você se chama?','Как тебя зовут?']],quiz:[['Выбери фразу «Я Ана».',['Eu sou Ana.','Eu Ana.','Eu está Ana.'],0,'В такой фразе нужен глагол sou.'],['Что сообщает Meu nome é Paulo?',['Меня зовут Паулу','Я из Паулу','Я ищу Паулу'],0,'Meu nome — «моё имя», é — «есть».']],write:['Собери фразу «Я Ана»: Ana / sou / Eu.',['eu sou ana'],'Eu sou Ana.'],mission:'Представься своим настоящим именем. Если хочешь, отправь фразу помощнику.',topic:'Ser: имя и личность'},
{id:'origem',title:'Сказать, откуда ты',scene:'Новый знакомый спрашивает, откуда ты приехал.',idea:'Sou de означает «Я из…». Перед названием Rússia обычно стоит a. Два маленьких слова de + a сливаются в da: sou da Rússia. С Москвой артикль обычно не нужен: sou de Moscou.',examples:[['Eu sou da Rússia.','Я из России.'],['Eu sou de Moscou.','Я из Москвы.'],['De onde você é?','Откуда ты?']],quiz:[['Как сказать «Я из России»?',['Eu sou da Rússia.','Eu sou Rússia.','Eu estou Rússia.'],0,'Sou da Rússia сообщает происхождение.'],['Из чего получилось da?',['de + a','de + o','em + a'],0,'De + a = da. Слияние делает фразу короче.']],write:['Напиши «Я из Москвы».',['eu sou de moscou','sou de moscou'],'Eu sou de Moscou.'],mission:'Скажи две вещи о себе: имя и город, откуда ты.',topic:'Происхождение и предлоги'},
{id:'estar',title:'Как ты сейчас?',scene:'Друг спрашивает, почему ты хочешь отдохнуть.',idea:'Ser помогает сказать, кто человек, а estar — в каком он состоянии или где находится. Sou brasileiro — «Я бразилец». Estou cansado — «Я устал». Правило «постоянное / временное» лишь подсказка: например, местонахождение человека выражаем через estar даже при долгом проживании.',examples:[['Eu estou cansado.','Я устал (говорит мужчина).'],['Eu estou cansada.','Я устала (говорит женщина).'],['Eu estou em casa.','Я дома.']],quiz:[['Как сказать «Я сейчас дома»?',['Eu estou em casa.','Eu sou em casa.','Eu tenho em casa.'],0,'Местонахождение человека: estar.'],['Почему cansado и cansada отличаются?',['Из-за рода говорящего','Из-за формальности','Из-за времени суток'],0,'Окончание согласуется с тем, о ком говорят.']],write:['Вставь один глагол: Eu ___ em casa.',['estou'],'estou'],mission:'Скажи, где ты и как себя чувствуешь. Например: Estou em casa. Estou bem.',topic:'Ser и estar',},
{id:'artigos',title:'Маленькие слова o и a',scene:'Ты показываешь другу книгу и дом на фотографии.',idea:'У существительных есть грамматический род. O livro — «книга», a casa — «дом». Он может отличаться от рода русского перевода. Учить удобнее сразу пару o livro, a casa. Um / uma вводят один, пока не уточнённый предмет: uma casa — «какой-то дом».',examples:[['o livro / um livro','эта, известная книга / какая-то книга'],['a casa / uma casa','этот, известный дом / какой-то дом'],['A casa é bonita.','Дом красивый.']],quiz:[['Выбери правильную пару для casa.',['a casa','o casa','eu casa'],0,'Casa — женского рода в португальском.'],['Uma casa обычно вводит…',['какой-то дом','несколько домов','моё имя'],0,'Uma — неопределённый артикль женского рода, единственного числа.']],write:['Поставь артикль a перед casa.',['a casa'],'a casa'],mission:'Запомни два слова вместе с артиклями: o livro и a casa.',topic:'Артикли и род'},
{id:'nao',title:'Спросить и сказать «нет»',scene:'Тебя спрашивают, говоришь ли ты по-португальски.',idea:'В простом вопросе порядок слов часто такой же, как в утверждении: Você fala português? На письме есть ?, в речи — вопросительная интонация. Чтобы отрицать действие, поставь não перед глаголом: Eu não falo. Не нужно добавлять отдельное «делать», как в английском.',examples:[['Você fala português?','Ты говоришь по-португальски?'],['Eu não falo português.','Я не говорю по-португальски.'],['Eu falo um pouco.','Я немного говорю.']],quiz:[['Где стоит não в «Я не говорю»?',['Eu não falo.','Eu falo não português.','Não eu português.'],0,'Обычное отрицание: não перед глаголом.'],['Что означает um pouco?',['Немного','Всегда','Вчера'],0,'Это полезное уточнение своего уровня.']],write:['Напиши «Я не говорю»: Eu / não / falo.',['eu nao falo'],'Eu não falo.'],mission:'Ответь на Você fala português? честно, короткой фразой.',topic:'Вопросы и отрицание'},
{id:'rotina',title:'Что ты делаешь каждый день',scene:'Вы знакомитесь с коллегой и говорите о работе и учёбе.',idea:'Глагол меняет окончание в зависимости от того, кто действует: eu moro — «я живу», você mora — «ты живёшь». Для многих глаголов на -ar с eu появляется -o: morar → moro, estudar → estudo. Не переноси это правило на все глаголы: у частых слов бывают особые формы.',examples:[['Eu moro no Brasil.','Я живу в Бразилии.'],['Eu estudo português.','Я изучаю португальский.'],['Você trabalha aqui?','Ты работаешь здесь?']],quiz:[['Как сказать «Я изучаю португальский»?',['Eu estudo português.','Eu estudar português.','Eu estuda português.'],0,'С eu: estudo. Estudar — начальная форма.'],['Кто живёт в фразе Você mora aqui?',['Ты / вы','Я','Мы'],0,'Você обращается к собеседнику.']],write:['Заполни: Eu ___ português. (estudar)',['estudo'],'estudo'],mission:'Расскажи о себе три факта: где живёшь, что изучаешь и где работаешь.',topic:'Настоящее время: глаголы на -ar'},
{id:'numeros',title:'Числа и цена',scene:'На рынке нужно понять небольшую цену.',idea:'Начни с маленького набора: um, dois, três, quatro, cinco — 1–5; seis, sete, oito, nove, dez — 6–10. Цена: Quanto custa? — «Сколько стоит?». Один реал — um real, несколько — reais. Число произносится перед названием валюты.',examples:[['Quanto custa?','Сколько стоит?'],['Custa cinco reais.','Стоит пять реалов.'],['Dois cafés, por favor.','Два кофе, пожалуйста.']],quiz:[['Тебе сказали cinco reais. Это…',['5 реалов','2 реала','10 реалов'],0,'Cinco — пять.'],['Как спросить цену?',['Quanto custa?','Como você se chama?','De onde você é?'],0,'Quanto — сколько, custa — стоит.']],write:['Напиши число 3 словом.',['tres'],'três'],mission:'Представь покупки за два, пять и десять реалов. Скажи цены вслух.',topic:'Числа и покупки'},
{id:'cafe',title:'Заказать в кафе',scene:'Ты хочешь кофе и воду.',idea:'Eu quero — «Я хочу». В кафе добавь por favor, чтобы вежливо попросить. Для вопроса о наличии удобно Tem…? — «Есть…?». Com — «с», sem — «без»: com açúcar / sem açúcar.',examples:[['Um café, por favor.','Один кофе, пожалуйста.'],['Eu quero água sem gás.','Я хочу воду без газа.'],['Tem pão de queijo?','Есть сырные булочки pão de queijo?']],quiz:[['Как попросить кофе без сахара?',['Um café sem açúcar, por favor.','Um café com açúcar.','Até amanhã, café.'],0,'Sem — без, com — с.'],['Что ты спрашиваешь с Tem água?',['Есть ли вода','Как зовут воду','Где ты живёшь'],0,'Tem…? часто используют в Бразилии, спрашивая о наличии.']],write:['Вставь «без»: café ___ açúcar.',['sem'],'sem'],mission:'Составь заказ из двух напитков и добавь por favor.',topic:'Просьбы и еда'},
{id:'onde',title:'Найти нужное место',scene:'Ты ищешь аптеку и хочешь уточнить, далеко ли она.',idea:'Onde fica…? — «Где находится…?». Perto — «близко», longe — «далеко». Для направления: à direita — «направо», à esquerda — «налево». В вопросе о расположении здания естественно fica: Onde fica a farmácia?',examples:[['Onde fica a farmácia?','Где аптека?'],['Fica perto daqui.','Она находится недалеко отсюда.'],['Vire à direita.','Поверните направо.']],quiz:[['Ты ищешь аптеку. Что спросить?',['Onde fica a farmácia?','Quanto custa a farmácia?','Eu sou a farmácia.'],0,'Onde спрашивает о месте.'],['À esquerda — это…',['Налево','Направо','Прямо сейчас'],0,'Esquerda — левая сторона.']],write:['Напиши «где» по-португальски.',['onde'],'onde'],mission:'Спроси дорогу до аптеки. Представь ответ: она недалеко.',topic:'Местонахождение и направления'},
{id:'amanha',title:'Планы на завтра',scene:'Друг предлагает встретиться завтра, а у тебя учёба.',idea:'Для простого плана удобно ir + начальная форма глагола. Eu vou estudar — «Я буду учиться / собираюсь учиться». Меняется vou, а estudar остаётся начальной формой. Amanhã — «завтра», hoje — «сегодня».',examples:[['Amanhã eu vou estudar.','Завтра я буду учиться.'],['Você vai trabalhar?','Ты будешь работать?'],['Hoje eu vou descansar.','Сегодня я собираюсь отдохнуть.']],quiz:[['После vou в плане ставим…',['начальную форму: estudar','форму estudo','местоимение eu ещё раз'],0,'Vou уже показывает, кто действует; второй глагол — в начальной форме.'],['Amanhã означает…',['Завтра','Вчера','Никогда'],0,'Не путай amanhã (завтра) и ontem (вчера).']],write:['Вставь: Amanhã eu vou ___. (учиться)',['estudar'],'estudar'],mission:'Расскажи один план на завтра. Спроси собеседника о его плане.',topic:'Будущее: ir + infinitivo'},
{id:'ontem',title:'Рассказать о вчерашнем дне',scene:'Друг спрашивает, чем ты занимался вчера.',idea:'Для завершённого события в прошлом нужна форма прошедшего времени. У многих глаголов на -ar с eu окончание -ei: estudar → estudei, trabalhar → trabalhei. Но ir — исключение: eu fui — «я ходил / ездил». На старте запомни эти три готовые формы.',examples:[['Ontem eu estudei português.','Вчера я занимался португальским.'],['Eu trabalhei ontem.','Я работал вчера.'],['Eu fui ao mercado.','Я ходил на рынок / в магазин.']],quiz:[['Как сказать «Вчера я занимался»?',['Ontem eu estudei.','Ontem eu vou estudar.','Amanhã eu estudo.'],0,'Ontem — вчера; estudei — завершённое действие в прошлом.'],['Fui в Eu fui ao mercado — это…',['Ходил / ездил','Собираюсь идти','Хожу каждый день'],0,'Fui — особая форма ir в прошедшем времени.']],write:['Заполни: Ontem eu ___ português. (estudar)',['estudei'],'estudei'],mission:'Напиши 3 фразы о себе: кто ты, что делал вчера и что планируешь завтра. Это твой первый мини-рассказ.',topic:'Прошедшее время: первые формы'}
]},
{id:'en',language:'en',title:'Английский: понятный старт',description:'Простые фразы для знакомства, быта и первых диалогов. Объяснения по-русски.',source:'A Digital Workbook for Beginning ESOL · Eric Dodson, Davida Jordan, Timothy Krause',url:'https://openlibrary-repo.ecampusontario.ca/jspui/bitstream/123456789/759/3/A-Digital-Workbook-for-Beginning-ESOL-1592955106.pdf',license:'CC BY 4.0',licenseUrl:'https://creativecommons.org/licenses/by/4.0/',lessons:[
{id:'hello',title:'Поздороваться и представиться',scene:'Ты знакомишься с новым соседом.',idea:'Hello — «Привет / Здравствуйте». В I am Anna слово am связывает «я» и имя. По-русски мы его пропускаем, по-английски — оставляем. I am часто сокращают до I’m.',examples:[['Hello! I am Anna.','Привет! Я Анна.'],["I’m Alex.",'Я Алекс.'],['What is your name?','Как тебя зовут?']],quiz:[['Выбери «Я Анна».',['I am Anna.','I Anna.','I is Anna.'],0,'С I используется am.'],['I’m — сокращение…',['I am','I is','You are'],0,'Апостроф заменяет пропущенную букву.']],write:['Собери: Anna / am / I.',['i am anna'],'I am Anna.'],mission:'Представься своим именем и спроси имя собеседника.',topic:'Приветствия и to be'},
{id:'be',title:'Я, ты и он',scene:'Ты знакомишь друга с коллегами.',idea:'У be есть три формы в настоящем: I am, you/we/they are, he/she/it is. Это короткая связка для имени, состояния или профессии. He is a teacher — «Он учитель». A здесь вводит профессию одного человека.',examples:[['You are a student.','Ты ученик.'],['She is a teacher.','Она учитель.'],['We are ready.','Мы готовы.']],quiz:[['Выбери форму: She ___ a teacher.',['is','am','are'],0,'С she используем is.'],['Выбери форму: We ___ ready.',['are','is','am'],0,'С we используем are.']],write:['Вставь: I ___ ready.',['am'],'am'],mission:'Скажи, что ты готов, а твой друг — учитель: I am ready. He is a teacher.',topic:'Формы am, is, are'},
{id:'things',title:'Назвать предметы',scene:'На столе телефон и книга.',idea:'A book — «какая-то книга», the book — «та самая, известная книга». An ставят перед гласным звуком: an apple. Выбор a/an зависит от звука, а не просто от буквы. На старте запомни готовые сочетания.',examples:[['This is a book.','Это книга.'],['This is an apple.','Это яблоко.'],['The book is here.','Книга здесь.']],quiz:[['Выбери сочетание.',['an apple','a apple','am apple'],0,'Apple начинается с гласного звука.'],['The book обычно означает…',['известную собеседнику книгу','любую профессию','много книг'],0,'The выделяет понятный из ситуации предмет.']],write:['Вставь: This is ___ book. (впервые называем предмет)',['a'],'a'],mission:'Найди вокруг книгу и телефон. Назови их: This is a book. This is a phone.',topic:'Предметы и артикли'},
{id:'questions',title:'Задать простой вопрос',scene:'Ты хочешь узнать, готов ли друг.',idea:'С am/is/are вопрос строится перестановкой: You are ready. → Are you ready? Чтобы сказать «нет», добавь not после связки: I am not ready. Для краткого ответа удобно Yes, I am / No, I am not.',examples:[['Are you ready?','Ты готов?'],['Yes, I am.','Да.'],['She is not here.','Её здесь нет.']],quiz:[['Выбери вопрос «Ты готов?»',['Are you ready?','You ready are?','Am you ready?'],0,'В вопросе are переносится перед you.'],['Где стоит not?',['She is not here.','She not is here.','Not she here.'],0,'Отрицание ставится после is.']],write:['Собери вопрос: you / Are / ready?',['are you ready'],'Are you ready?'],mission:'Спроси друга, готов ли он. Ответь за него утвердительно и отрицательно.',topic:'Вопросы и отрицание с be'},
{id:'daily',title:'Обычный день',scene:'Ты рассказываешь, где живёшь и что делаешь.',idea:'Для обычных действий: I live — «я живу», I work — «я работаю». С he/she обычно добавляется -s: she works. С be правило другое: I am. Не добавляй am к обычному I work.',examples:[['I live in Brazil.','Я живу в Бразилии.'],['I study English.','Я изучаю английский.'],['She works here.','Она работает здесь.']],quiz:[['Выбери «Я работаю здесь».',['I work here.','I am work here.','I works here.'],0,'С I нужен work без am и без -s.'],['Выбери «Она работает».',['She works.','She work.','She am work.'],0,'С she в обычном настоящем времени: works.']],write:['Вставь: I ___ English. (изучаю)',['study'],'study'],mission:'Напиши две правдивые фразы о себе с I live и I study.',topic:'Обычное настоящее время'},
{id:'please',title:'Попросить в кафе',scene:'Ты заказываешь воду и кофе.',idea:'I would like… — вежливое «Я бы хотел…». В речи часто I’d like. Для короткого заказа можно A coffee, please. Please — «пожалуйста» в просьбе, thank you — «спасибо» после неё.',examples:[['A coffee, please.','Кофе, пожалуйста.'],['I would like some water.','Я бы хотел воды.'],['Thank you!','Спасибо!']],quiz:[['Что добавишь к просьбе?',['please','yesterday','ready'],0,'Please смягчает просьбу.'],['I’d like означает…',['Я бы хотел','Я вчера работал','Ты готов'],0,'Это сокращение I would like.']],write:['Напиши «спасибо» по-английски.',['thank you','thanks'],'Thank you!'],mission:'Разыграй заказ: поздоровайся, попроси кофе и поблагодари.',topic:'Вежливые просьбы'}
]}
];

// Vary answer positions while preserving the correct option.
window.BoraCourses.forEach(c=>c.lessons.forEach((l,i)=>l.quiz.forEach((q,j)=>{const n=(i+j)%q[1].length;q[1]=q[1].slice(n).concat(q[1].slice(0,n));q[2]=(q[2]-n+q[1].length)%q[1].length})));

// Additional greetings have original human recordings in the source textbook.
window.BoraCourses[0].lessons[0].examples.push(["Bom dia!","Доброе утро!"],["Boa tarde!","Добрый день!"],["Boa noite!","Добрый вечер / спокойной ночи!"]);
window.BoraCourses[0].lessons.find(l=>l.id==="artigos").examples=[["o livro","эта, известная книга"],["um livro","какая-то книга"],["a casa","этот, известный дом"],["uma casa","какой-то дом"],["A casa é bonita.","Дом красивый."]];
